FROM purchase
WHERE purchase_date >= DATE '2025-01-01' AND purchase_date < DATE '2026-01-01';

SELECT c.company_id, c.name
FROM company c
WHERE EXISTS (
  SELECT 1 FROM game g WHERE g.publisher_company_id = c.company_id
)
